package com.crm.core.actuator;

import com.crm.core.security.UserAccountPrincipal;
import com.crm.core.service.OrganizationFeatureService;
import org.springframework.boot.actuate.endpoint.annotation.ReadOperation;
import org.springframework.boot.actuate.endpoint.annotation.Selector;
import org.springframework.boot.actuate.endpoint.web.annotation.WebEndpoint;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Component;
import java.util.Map;

@Component
@WebEndpoint(id = "tenant-feature-flags")
public class FeatureFlagsActuatorEndpoint {

    private final OrganizationFeatureService featureService;

    public FeatureFlagsActuatorEndpoint(OrganizationFeatureService featureService) {
        this.featureService = featureService;
    }

    @ReadOperation
    public Map<String, Boolean> getFeatureFlags(@Selector Long organizationId) {
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        if (auth != null && auth.getPrincipal() instanceof UserAccountPrincipal principal) {
            if (!principal.getOrganizationId().equals(organizationId) && !principal.isPlatformAdmin()) {
                throw new AccessDeniedException("Cannot inspect feature flag configurations of another organization");
            }
        }
        return featureService.getFeatureStateForOrg(organizationId);
    }
}
